recognized_test_commands.command:
/bin/bash -lc "cat >> .codex-role-output/checkpoint.md <<'EOF'

Investigation:
- WordPress packages are collected by "'`scan/base.go` with WP-CLI status values.
- `wordpress.FillWordPress` loops over all themes/plugins and requests WPVulnDB for each; its TODO names this flag.
- Existing per-server `WordPress.IgnoreInactive` filters CVEs later in `models.FilterInactiveWordPressLibs`, after API requests, so it does not save calls.
- `ReportCmd.SetFlags` registers report flags; `config.TOMLLoader.Load` selectively copies decoded settings into `Conf`.
- Root cause: no global `WpIgnoreInactive` flag/config field, and no filtering before the API loops.
- Hypothesis: filtering the package list at the start of `FillWordPress` before iteration will prevent inactive package API calls and remove them from the resulting package list, while preserving the default behavior.
EOF
cat > wordpress/wordpress_test.go <<'"'EOF'
package wordpress

import (
    \"reflect\"
    \"testing\"

    \"github.com/future-architect/vuls/models\"
)

func TestRemoveInactives(t *testing.T) {
    packages := models.WordPressPackages{
        {Name: \"core\", Type: models.WPCore},
        {Name: \"active-theme\", Type: models.WPTheme, Status: \"active\"},
        {Name: \"inactive-plugin\", Type: models.WPPlugin, Status: models.Inactive},
        {Name: \"must-use-plugin\", Type: models.WPPlugin, Status: \"must-use\"},
        {Name: \"inactive-theme\", Type: models.WPTheme, Status: models.Inactive},
    }
    want := models.WordPressPackages{packages[0], packages[1], packages[3]}
    if got := removeInactives(packages); "'!reflect.DeepEqual(got, want) {
        t.Fatalf("removeInactives() = %#v, want %#v", got, want)
    }
    if got := removeInactives(models.WordPressPackages{packages[2], packages[4]}); got != nil {
        t.Fatalf("removeInactives(all inactive) = %#v, want nil", got)
    }
}
EOF
GOPROXY=off GOSUMDB=off go test ./wordpress -run TestRemoveInactives -count=1'
